  async function loadOverview(){state.overview=await api('/api/admin/overview');}
  async function dashboard(){if(!state.overview)await loadOverview();const s=state.overview.stats;layout(tr('dashboard'),tr('overview'),`<section class="admin-stats"><article class="admin-stat"><span>${tr('accounts')}</span><strong>${s.users}</strong><small>${tr('contributors')}: ${s.contributors} · ${tr('admins')}: ${s.admins}</small></article><article class="admin-stat"><span>${tr('articles')} / ${tr('briefs')}</span><strong>${s.articles} / ${s.briefs}</strong><small>${s.published} ${tr('published')} · ${s.drafts} ${tr('drafts')}</small></article><article class="admin-stat"><span>${tr('validation')}</span><strong>${s.pending}</strong><small>${s.rejected} ${tr('rejected')}</small></article><article class="admin-stat"><span>${tr('newUsers')}</span><strong>${s.newUsers}</strong><small>${s.views} ${tr('views')} · ${s.scheduled} ${tr('scheduled')}</small></article></section><section class="admin-grid"><article class="admin-panel-card"><h2>${tr('activity')}</h2><div class="admin-list">${state.overview.audit.length?state.overview.audit.map(a=>`<div class="admin-audit"><span><b>${escape(a.action)}</b> · ${escape(a.target_type||tr('element'))}<br><small>${escape(a.admin_name||'Administration')}</small></span><small>${fmt(a.created_at)}</small></div>`).join(''):`<p class="admin-empty">${tr('noActivity')}</p>`}</div></article><article class="admin-panel-card"><h2>${tr('validation')}</h2><div class="admin-list"><div class="admin-audit"><span>${tr('pending')}</span><b>${s.pending}</b></div><div class="admin-audit"><span>${tr('openReports')}</span><b>${s.reports}</b></div><div class="admin-audit"><span>${tr('totalViews')}</span><b>${s.views}</b></div></div></article></section>`)}
  async function loadNotifications(){state.notifications=(await api('/api/admin/notifications')).items||[];const unread=state.notifications.filter(n=>!n.read_at).length;const badge=document.querySelector('.admin-notice-count');if(badge){badge.hidden=!unread;badge.textContent=unread}}
  async function notifications(){await loadNotifications();layout(tr('notifications'),tr('notificationsInfo'),`<section class="admin-table">${state.notifications.length?state.notifications.map(n=>`<article class="admin-row admin-notification"><i class="admin-notification-unread" ${n.read_at?'style="visibility:hidden"':''}></i><div><b>${escape(n.title)}</b><p>${escape(n.body||'')}</p><small>${fmt(n.created_at)}</small></div><div class="admin-notification-actions"><button class="admin-icon-button admin-compact" data-notification-link="${n.target_url}" aria-label="${tr('open')}" title="${tr('open')}">↗</button><button class="admin-icon-button admin-compact" data-notification-state="${n.id}" data-read="${n.read_at?'unread':'read'}" aria-label="${n.read_at?tr('markUnread'):tr('markRead')}" title="${n.read_at?tr('markUnread'):tr('markRead')}">${n.read_at?'○':'✓'}</button><button class="admin-icon-button admin-compact admin-danger" data-notification-delete="${n.id}" aria-label="${tr('delete')}" title="${tr('delete')}">×</button></div></article>`).join(''):`<p class="admin-empty">${tr('noNotifications')}</p>`}</section>`)}
  async function loadUsers(){state.users=(await api('/api/admin/users')).items||[]}
  function accounts(){const q=state.filters.query.toLowerCase();const role=state.filters.role||'';const items=state.users.filter(u=>`${u.name} ${u.email} ${u.preferred_topic}`.toLowerCase().includes(q)&&(!role||u.role===role));layout(tr('accounts'),tr('accountsInfo'),`<div class="admin-toolbar"><input id="account-search" class="admin-search" placeholder="${tr('searchAccount')}" value="${escape(state.filters.query)}"><select id="account-role-filter" class="admin-filter"><option value="">${tr('allRoles')}</option><option value="USER" ${role==='USER'?'selected':''}>${tr('user')}</option><option value="CONTRIBUTOR" ${role==='CONTRIBUTOR'?'selected':''}>${tr('contributors')}</option><option value="ADMIN" ${role==='ADMIN'?'selected':''}>${tr('admins')}</option></select><button class="admin-button" id="new-account">＋ ${tr('newAccount')}</button></div><section class="admin-table">${items.length?items.map(u=>`<article class="admin-row"><div class="admin-row-main"><button class="admin-row-title" data-user-open="${u.id}">${escape(u.name)}</button><div class="admin-row-meta"><span>${escape(u.email)}</span><span class="admin-chip">${escape(u.role)}</span><span class="admin-chip">${escape(u.preferred_topic||'—')}</span>${u.is_banned?`<span class="admin-chip alert">${tr('suspended')}</span>`:''}</div></div><div class="admin-row-actions"><button class="admin-icon-button admin-compact" data-user-open="${u.id}" aria-label="${tr('viewAccount')}" title="${tr('viewAccount')}">›</button></div></article>`).join(''):`<p class="admin-empty">${tr('noAccounts')}</p>`}</section>`)}
  async function loadContent(){state.content=(await api('/api/admin/content')).items||[]}
  function content(){const f=state.filters;const items=state.content.filter(i=>(!f.query||`${i.title} ${i.slug}`.toLowerCase().includes(f.query.toLowerCase()))&&(!f.type||i.type===f.type)&&(!f.category||i.category===f.category)&&(!f.status||i.status===f.status));const opts=(arr,current,label)=>`<option value="">${label}</option>${arr.map(v=>`<option value="${escape(v)}" ${current===v?'selected':''}>${escape(typeLabel(v))}</option>`).join('')}`;layout(tr('content'),tr('contentInfo'),`<div class="admin-toolbar"><input id="content-query" class="admin-search" placeholder="${tr('search')}" value="${escape(f.query)}"><select id="content-type" class="admin-filter">${opts(typeKeys,f.type,tr('allTypes'))}</select><select id="content-category" class="admin-filter"><option value="">${tr('allCategories')}</option>${categories.map(c=>`<option value="${c}" ${f.category===c?'selected':''}>${categoryLabel(c)}</option>`).join('')}</select><select id="content-status" class="admin-filter"><option value="">${tr('allStatuses')}</option>${['draft','review','scheduled','published','archived'].map(x=>`<option value="${x}" ${f.status===x?'selected':''}>${escape(tr(x))}</option>`).join('')}</select><button class="admin-button" id="new-content">＋ ${tr('newContent')}</button></div><section class="admin-table">${items.length?items.map(i=>`<article class="admin-row"><div class="admin-row-main"><span class="admin-row-title">${escape(i.title)}</span><div class="admin-row-meta"><span class="admin-chip">${escape(typeLabel(i.type))}</span><span>${escape(categoryLabel(i.category))}</span><span>${escape(tr(i.status))}</span><span>${fmt(i.scheduled_at||i.published_at||i.updated_at)}</span></div></div><div class="admin-row-actions"><button class="admin-icon-button admin-compact" data-content-edit="${i.id}" aria-label="${tr('edit')}" title="${tr('edit')}">✎</button><button class="admin-icon-button admin-compact admin-danger" data-content-delete="${i.id}" aria-label="${tr('delete')}" title="${tr('delete')}">×</button></div></article>`).join(''):`<p class="admin-empty">${tr('noContent')}</p>`}</section>`)}
  async function validation(){state.submissions=(await api('/api/admin/submissions')).items||[];layout(tr('validation'),tr('reviewInfo'),`<section class="admin-table">${state.submissions.length?state.submissions.map(item=>`<article class="admin-row"><div class="admin-row-main"><span class="admin-row-title">${escape(item.title)}</span><div class="admin-row-meta"><span>${escape(item.author_name||'—')}</span><span class="admin-chip">${escape(item.type==='article'?tr('articles'):tr('briefs'))}</span><span>${escape(item.category)}</span><span>${fmt(item.submitted_at)}</span></div></div><div class="admin-row-actions"><button class="admin-icon-button admin-compact" data-review="${escape(item.id)}" aria-label="${tr('readSubmission')}" title="${tr('readSubmission')}">↗</button></div></article>`).join(''):`<p class="admin-empty">${tr('noPending')}</p>`}</section>`);root.querySelectorAll('[data-review]').forEach(button=>button.onclick=()=>openSubmission(button.dataset.review))}
  async function openSubmission(id){const data=await api(`/api/admin/submissions?id=${encodeURIComponent(id)}`),item=data.item;const d=dialog(`<div class="admin-dialog-inner"><header class="admin-dialog-head"><div><p class="admin-kicker">${escape(item.author_name||'')}</p><h2>${escape(item.title)}</h2><p>${escape(item.category)} · ${escape(item.type)} · ${fmt(item.submitted_at)}</p></div><button class="admin-icon-button admin-compact" data-dialog-close aria-label="${tr('close')}">×</button></header>${item.cover_url?`<img src="${escape(item.cover_url)}" alt="${escape(item.title)}" style="width:100%;max-height:340px;object-fit:cover;border-radius:12px">`:''}<p>${escape(item.excerpt)}</p><article style="white-space:pre-wrap;line-height:1.75">${escape(item.body)}</article><h3>${tr('sources')}</h3><ul>${(data.sources||[]).map(source=>`<li><a href="${escape(source.url)}" target="_blank" rel="noopener noreferrer">${escape(source.label)}</a> · ${escape(source.publisher||'')}</li>`).join('')}</ul><footer class="admin-dialog-actions"><button class="admin-button admin-danger" data-reject>${tr('reject')}</button><button class="admin-button" data-dialog-close>${tr('close')}</button><button class="admin-button" data-approve>${tr('approve')}</button></footer></div>`);d.querySelector('[data-approve]').onclick=async()=>{if(!confirm(tr('confirmApprove')))return;await api('/api/admin/submissions',{method:'POST',body:JSON.stringify({id,action:'approve'})});d.close();state.overview=null;await validation()};d.querySelector('[data-reject]').onclick=async()=>{const reason=prompt(tr('reasonPrompt'));if(!reason)return;await api('/api/admin/submissions',{method:'POST',body:JSON.stringify({id,action:'reject',reason})});d.close();state.overview=null;await validation()}}
  async function analytics(){const qs=new URLSearchParams({period:state.period});state.analytics=await api(`/api/admin/analytics?${qs}`);const a=state.analytics;const list=(title,items)=>`<article class="admin-panel-card"><h2>${title}</h2>${items.length?items.map(item=>`<div class="admin-audit"><a href="/${locale}/articles/${encodeURIComponent(item.slug)}/">${escape(item.title)}</a><b>${item.value}</b></div>`).join(''):`<p class="admin-empty">${tr('loadError')}</p>`}</article>`;layout(tr('analytics'),`${tr('metricsSince')} ${a.from}.`, `<div class="admin-toolbar"><label>${tr('period')} <select class="admin-filter" id="analytics-period"><option value="1d" ${state.period==='1d'?'selected':''}>${tr('today')}</option><option value="7d" ${state.period==='7d'?'selected':''}>7 ${tr('days')}</option><option value="30d" ${state.period==='30d'?'selected':''}>30 ${tr('days')}</option><option value="90d" ${state.period==='90d'?'selected':''}>90 ${tr('days')}</option></select></label></div><section class="admin-stats"><article class="admin-stat"><span>${tr('views')}</span><strong>${a.totals.views}</strong></article><article class="admin-stat"><span>${tr('likes')}</span><strong>${a.totals.likes}</strong></article><article class="admin-stat"><span>${tr('favorites')}</span><strong>${a.totals.favorites}</strong></article></section><section class="admin-grid">${list(tr('topViews'),a.topViews)}${list(tr('topLikes'),a.topLikes)}${list(tr('topFavorites'),a.topFavorites)}${list(tr('low'),a.leastViews)}</section>`);root.querySelector('#analytics-period').onchange=event=>{state.period=event.target.value;analytics()}}
  const rate=(value,total)=>Number(total)>0?`${(Number(value||0)/Number(total)*100).toFixed(1)} %`:'—';
  async function newsletter(){state.newsletter=await api('/api/admin/newsletter');const n=state.newsletter,s=n.subscribers,t=n.totals;layout('Newsletter',`${tr('newsletterInfo')} ${tr('nextEdition')} : ${escape(n.nextRun.localDate)}.`,`<section class="admin-stats admin-newsletter-stats"><article class="admin-stat"><span>${tr('activeSubscribers')}</span><strong>${Number(s.active||0)}</strong><small>${Number(s.new7d||0)} ${tr('newSevenDays')}</small></article><article class="admin-stat"><span>${tr('sentEditions')}</span><strong>${Number(t.sent||0)}</strong><small>${Number(t.total||0)} ${tr('generatedEditions')}</small></article><article class="admin-stat"><span>${tr('deliverability')}</span><strong>${rate(t.delivered,t.emails)}</strong><small>${Number(t.delivered||0)} / ${Number(t.emails||0)}</small></article><article class="admin-stat"><span>${tr('opensClicks')}</span><strong>${rate(t.opens,t.delivered)}</strong><small>${rate(t.clicks,t.delivered)} ${tr('clicks')}</small></article></section><div class="admin-toolbar"><input id="subscriber-search" class="admin-search" type="search" placeholder="${tr('searchSubscriber')}" value="${escape(state.filters.subscriber)}"><button class="admin-button" id="subscriber-search-button">${tr('search')}</button></div><section class="admin-grid"><article class="admin-panel-card admin-newsletter-editions"><h2>${tr('editionHistory')}</h2><div class="admin-list">${n.editions.length?n.editions.map(e=>`<button class="admin-edition-row" data-edition="${e.id}"><span><b>${escape(e.subject)}</b><small>${escape(e.locale.toUpperCase())} · ${fmt(e.sent_at||e.created_at)}</small></span><span class="admin-chip ${e.status==='FAILED'?'alert':''}">${escape(e.status)}</span></button>`).join(''):`<p class="admin-empty">${tr('noEdition')}</p>`}</div></article><article class="admin-panel-card"><h2>${tr('systemStatus')}</h2><dl class="admin-detail-grid"><div><dt>${tr('lastRun')}</dt><dd>${n.lastRun?escape(n.lastRun.status):tr('none')}</dd></div><div><dt>${tr('nextRun')}</dt><dd>${escape(n.nextRun.localDate)} · 08:00</dd></div><div><dt>Bounces</dt><dd>${Number(t.bounces||0)}</dd></div><div><dt>${tr('errors')}</dt><dd>${Number(t.errors||0)+Number(s.sync_errors||0)}</dd></div><div><dt>${tr('unsubscribes')}</dt><dd>${Number(s.unsubscribed||0)}</dd></div><div><dt>Timezone</dt><dd>Africa/Casablanca</dd></div></dl></article></section><section id="newsletter-subscriber-results" class="admin-table admin-newsletter-subscribers" hidden></section>`)}
  async function searchSubscribers(){const q=root.querySelector('#subscriber-search')?.value||'';state.filters.subscriber=q;const data=await api(`/api/admin/newsletter?view=subscribers&q=${encodeURIComponent(q)}`);const box=root.querySelector('#newsletter-subscriber-results');box.hidden=false;box.innerHTML=data.items.length?data.items.map(item=>`<article class="admin-row"><div><b>${escape(item.email)}</b><small>${escape(item.locale.toUpperCase())} · ${escape(item.status)} · ${fmt(item.subscribed_at||item.created_at)}</small></div><span class="admin-chip">${escape(item.brevo_sync_status)}</span></article>`).join(''):`<p class="admin-empty">${tr('noSubscriber')}</p>`}
  async function openEdition(id){const data=await api(`/api/admin/newsletter?view=edition&id=${encodeURIComponent(id)}&refresh=1`),e=data.edition;const d=dialog(`<div class="admin-dialog-inner"><header class="admin-dialog-head"><div><p class="admin-kicker">Newsletter · ${escape(e.locale.toUpperCase())}</p><h2>${escape(e.subject)}</h2><p>${fmt(e.sent_at||e.created_at)} · ${escape(e.status)}</p></div><button class="admin-icon-button admin-compact" data-dialog-close aria-label="${tr('close')}">×</button></header><dl class="admin-detail-grid"><div><dt>${tr('recipients')}</dt><dd>${Number(e.subscriber_count||0)}</dd></div><div><dt>${tr('delivered')}</dt><dd>${Number(e.delivered_count||0)}</dd></div><div><dt>${tr('opens')}</dt><dd>${Number(e.open_count||0)}</dd></div><div><dt>${tr('clicks')}</dt><dd>${Number(e.click_count||0)}</dd></div><div><dt>Bounces</dt><dd>${Number(e.bounce_count||0)}</dd></div><div><dt>${tr('errors')}</dt><dd>${Number(e.error_count||0)}</dd></div></dl><h3>${tr('selectedContent')}</h3><ol class="admin-edition-items">${data.items.map(item=>`<li><a href="/${locale}/articles/${encodeURIComponent(item.slug)}/" target="_blank">${escape(item.title)}</a><small>${escape(item.category)} · score ${Number(item.score).toFixed(1)}</small></li>`).join('')}</ol>${data.links.length?`<h3>${tr('topLinks')}</h3><ul>${data.links.map(link=>`<li>${escape(link.url)} · ${Number(link.clicks)}</li>`).join('')}</ul>`:''}<footer class="admin-dialog-actions"><button class="admin-button" data-dialog-close>${tr('close')}</button></footer></div>`);return d}
